fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
    // Convert 1-based index k to 0-based index for Rust
    let index = k - 1;
    
    // Create a new vector that contains elements before and after the index
    let mut new_list = Vec::with_capacity(list.len() - 1);
    
    // Add elements before the k-th element
    new_list.extend_from_slice(&list[0..index]);
    // Add elements after the k-th element
    new_list.extend_from_slice(&list[index + 1..]);
    
    new_list
}